#the user functions of Exudyn as they are, for docs/dev/internals/userFunctions.md, section 4 (revision2026c step
#RG12.2, #2982): every user function parameter of the items and the user functions of the MainSystem, with the
#arguments and the result as their definitions write them, the class of signature, and whether a symbolic user
#function can take its place (src/Autogenerated/PySymbolicUserFunctionSet.h). It changes nothing.
#
#usage:  python tools/benchmarks/userFunctionInterfaces.py             #the table per signature class, as Markdown
#        python tools/benchmarks/userFunctionInterfaces.py --all       #and the table of every user function
import argparse
import ast
import inspect
import os
import re
import sys
import textwrap

root = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..'))
sys.path.insert(0, os.path.join(root, 'tools', 'generators'))
sys.path.insert(0, os.path.join(root, 'definitions'))
import definitionLoader                                                     # noqa: E402

#the user functions of the MainSystem, which are not item parameters (pybindMainSystem.py)
mainSystemFunctions = [('MainSystem', 'preStepUserFunction', ['MainSystem', 'Real'], 'bool'),
                       ('MainSystem', 'postStepUserFunction', ['MainSystem', 'Real'], 'bool'),
                       ('MainSystem', 'postNewtonFunction', ['MainSystem', 'Real'], 'Vector2D')]

fixedSizes = ['Vector2D', 'Vector3D', 'Vector6D', 'Matrix3D', 'Matrix6D']


def Annotations(function):
    """the argument annotations and the result annotation of a user function def, as written"""
    node = ast.parse(textwrap.dedent(inspect.getsource(function))).body[0]
    arguments = [ast.unparse(a.annotation) if a.annotation is not None else '?' for a in node.args.args]
    return arguments, (ast.unparse(node.returns) if node.returns is not None else 'None')


def SignatureClass(arguments, result):
    """the class of a signature, as the boundary treats it: what goes in beyond mbs, t and the item number, what comes out"""
    inputs = set(arguments[2:])
    if 'Graphics' in result:
        return 'graphics'
    if 'Matrix' in result and result not in fixedSizes:
        return 'run-time vectors in, matrix out'
    if 'Vector' in inputs or result == 'Vector':
        return 'run-time vectors'
    if any(a in fixedSizes for a in inputs) or result in fixedSizes:
        return 'fixed-size vectors and matrices'
    return 'scalars'


def SymbolicSet():
    """(item, user function) pairs with a symbolic version"""
    text = open(os.path.join(root, 'src', 'Autogenerated', 'PySymbolicUserFunctionSet.h'), encoding='utf-8').read()
    return set(re.findall(r'itemTypeName == "(\w+)" && userFunctionName == "(\w+)"', text))


def Rows():
    rows = []
    symbolic = SymbolicSet()
    for moduleName in definitionLoader.itemModules:
        for definition in __import__(moduleName).definitions:
            for member in definition['members']:
                if member.get('userFunction') is None:
                    continue
                (arguments, result) = Annotations(member['userFunction'])
                rows.append((definition['className'], member['pythonName'], arguments, result,
                             (definition['className'], member['pythonName']) in symbolic))
    for (item, name, arguments, result) in mainSystemFunctions:
        rows.append((item, name, arguments, result, (item, name) in symbolic))
    return rows


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description='the user functions as they are')
    parser.add_argument('--all', action='store_true', help='also the table of every user function')
    arguments = parser.parse_args()
    rows = Rows()
    classes = {}
    for row in rows:
        classes.setdefault(SignatureClass(row[2], row[3]), []).append(row)
    print('<!-- written by tools/benchmarks/userFunctionInterfaces.py -->')
    print('| signature class | user functions | with symbolic version | distinct signatures |')
    print('|---|---:|---:|---:|')
    for (name, group) in sorted(classes.items(), key=lambda entry: -len(entry[1])):
        signatures = set((tuple(row[2]), row[3]) for row in group)
        print('| ' + name + ' | ' + str(len(group)) + ' | ' + str(sum(1 for row in group if row[4])) + ' | '
              + str(len(signatures)) + ' |')
    print('| **all** | ' + str(len(rows)) + ' | ' + str(sum(1 for row in rows if row[4])) + ' | '
          + str(len(set((tuple(row[2]), row[3]) for row in rows))) + ' |')
    if arguments.all:
        print()
        print('| item | user function | arguments after mbs, t | result | class | symbolic |')
        print('|---|---|---|---|---|---|')
        for row in sorted(rows, key=lambda row: (SignatureClass(row[2], row[3]), row[0], row[1])):
            print('| ' + row[0] + ' | ' + row[1] + ' | ' + ', '.join(row[2][2:]) + ' | ' + row[3] + ' | '
                  + SignatureClass(row[2], row[3]) + ' | ' + ('yes' if row[4] else '-') + ' |')
